use std::{num::Saturating, time::Instant};

use tfhe::core_crypto::prelude::{
    lwe_ciphertext_add, lwe_ciphertext_add_assign, lwe_ciphertext_cleartext_mul_assign, Cleartext,
};

use crate::{lut::MNLUT, nlwe::NLWE, packed_lut::PackedMNLUT, Context, LUT, LWE};

impl crate::PublicKey {
    pub fn blind_sp(
        &self,
        next_mat: &Vec<Vec<u64>>,
        dep: LWE,
        arv: LWE,
        ctx: &Context,
    ) -> Vec<LWE> {
        let n = next_mat.len();
        let start = Instant::now();
        let colonne = self.blind_extract_vec_clear(&next_mat, &arv, ctx);
        let d = start.elapsed();
        println!("extraction de colonne: {:?}", d);
        let mut vecteur = vec![dep.clone()];
        let start = Instant::now();

        for i in 1..n {
            vecteur.push(self.blind_array_access(&vecteur[i - 1], &colonne, ctx));
        }

        let d = start.elapsed();
        println!("reconstruction du chemin: {:?}", d);
        vecteur
    }

    ///Todo:
    /// mat_next: [[u64,256],256]
    /// col= LWE2
    /// extraire la colonne arrivé avec le orincipe de félix :
    ///
    /// avoir la LUT2,2
    /// ajouter les default_nlwes dans :
    ///    -from_plain
    ///    -from_plain_trivially
    /// pour verufier : test_blind_tensor_increment
    /// faire une fontion blind_rotate sur une LUTmn

  pub fn extract_lut_2_2_from_mat_next(
    &self,
    next_mat: &Vec<Vec<u64>>,
    arv: NLWE,
    ctx: &Context,
) -> MNLUT {
    // One-hot de la destination
    let one = NLWE::from_plain_trivially(1, 2, ctx, &self);
    let start = Instant::now();
    let one_hot = MNLUT::blind_tensor_lift(&arv, &one, ctx, self);
    let d = start.elapsed();
    println!("Le temps du one hot {:?}", d);

    let n = next_mat.len();

    let mut vec_nlwes = Vec::with_capacity(n);
    for i in 0..n {
        let line = &next_mat[i];

        // 3 digits (hi, mid, lo) -> base 16 (4 bits chacun)
        let mut hi = self.allocate_and_trivially_encrypt_lwe(0, ctx);
        let mut mid = self.allocate_and_trivially_encrypt_lwe(0, ctx);
        let mut lo = self.allocate_and_trivially_encrypt_lwe(0, ctx);

        for j_u64 in 0u64..(n as u64) {
    let j = j_u64 as usize; // pour indexer les tableaux
    let v = line[j];

    // tes digits (exemple avec 3 nibbles) :
    let (lo_d, mid_d, hi_d) = if v == u64::MAX {
        (0u64, 0u64, 0u64)
    } else {
        ( (v & 0xF) as u64, ((v >> 4) & 0xF) as u64, ((v >> 8) & 0xF) as u64 )
    };

    // on utilise j (usize) pour one_hot.at(...), et des u64 pour Cleartext(...)
    let mut maybe = one_hot.at(j_u64, ctx).digits[0].clone();
    lwe_ciphertext_cleartext_mul_assign(&mut maybe, Cleartext(lo_d));
    lwe_ciphertext_add_assign(&mut lo, &maybe);

    let mut maybe = one_hot.at(j_u64, ctx).digits[0].clone();
    lwe_ciphertext_cleartext_mul_assign(&mut maybe, Cleartext(mid_d));
    lwe_ciphertext_add_assign(&mut mid, &maybe);

    let mut maybe = one_hot.at(j_u64, ctx).digits[0].clone();
    lwe_ciphertext_cleartext_mul_assign(&mut maybe, Cleartext(hi_d));
    lwe_ciphertext_add_assign(&mut hi, &maybe);
}
        // 3 digits (hi, mid, lo)
        vec_nlwes.push(NLWE { digits: vec![hi, mid, lo] });
    }

    // IMPORTANT : 3 digits attendus = 3 produits ci-dessus
    MNLUT::from_nlwes(&vec_nlwes, 3, self, ctx)
}


    pub fn blind_sp_big(
        &self,
        next_mat: &Vec<Vec<u64>>,
        dep: NLWE,
        arv: NLWE,
        ctx: &Context,
    ) -> Vec<NLWE> {
        let colonne = self.extract_lut_2_2_from_mat_next(next_mat, arv, ctx);
        let pack_col= PackedMNLUT::from_mnlut(&colonne, ctx, self);
        let mut vecteur = vec![dep.clone()];
        let n = next_mat.len();
        let start = Instant::now();
        for i in 1..n {
            let start2 = Instant::now();

            vecteur.push(pack_col.blind_tensor_access(&vecteur[i - 1], ctx, &self));
            let d2= start2.elapsed();
            println!("temps pour access {i} est de {:?}",d2);
        }
        let d = start.elapsed();
        println!("reconstruction du chemin big {:?}", d);
        vecteur
    }
}
