#[test]
fn test_blind_sp_big_1830() {
    use std::collections::HashMap;
    use std::fs::File;
    use std::io::{BufRead, BufReader};

    // ---- 1) Charger le mapping original_id -> new_id (depuis node_mapping.csv) ----
    // Format attendu: header "new_id,original_id", puis lignes "k,orig"
    let mut orig2new: HashMap<u64, u64> = HashMap::new();
    if let Ok(f) = File::open("node_mapping.csv") {
        let r = BufReader::new(f);
        for (i, line) in r.lines().enumerate() {
            let line = line.expect("Ligne illisible dans node_mapping.csv");
            if i == 0 && line.trim().starts_with("new_id") { continue; }
            let mut it = line.split(',').map(|t| t.trim());
            let new_id: u64 = it.next().and_then(|s| s.parse().ok()).expect("new_id invalide");
            let orig_id: u64 = it.next().and_then(|s| s.parse().ok()).expect("original_id invalide");
            orig2new.insert(orig_id, new_id);
        }
    } else {
        // Pas de mapping ? On pourra quand même accepter des indices déjà 0..n-1.
        eprintln!("node_mapping.csv introuvable — on supposera que next_hop.csv est déjà remappé.");
    }

    // ---- 2) Charger next_hop.csv en matrice de chaînes pour connaître n et remapper ensuite ----
    let f = File::open("next_hop.csv").expect("Impossible d'ouvrir next_hop.csv");
    let r = BufReader::new(f);
    let mut tokens: Vec<Vec<String>> = Vec::new();
    for line in r.lines() {
        let line = line.expect("Ligne illisible dans next_hop.csv");
        let row: Vec<String> = line
            .trim()
            .split(',')
            .map(|t| t.trim().to_string())
            .filter(|t| !t.is_empty())
            .collect();
        tokens.push(row);
    }
    let n = tokens.len();
    assert!(n > 0, "next_hop.csv vide ?");
    for (i, row) in tokens.iter().enumerate() {
        assert_eq!(row.len(), n, "La ligne {} n'a pas {} colonnes", i, n);
    }

    // ---- 3) Remap en Vec<Vec<u64>>: -1 -> u64::MAX ; sinon original_id -> new_id ; sinon déjà 0..n-1 ----
    let mut next_hop: Vec<Vec<u64>> = vec![vec![u64::MAX; n]; n];
    for i in 0..n {
        for j in 0..n {
            let t = tokens[i][j].as_str();
            if t == "-1" {
                next_hop[i][j] = u64::MAX;
            } else {
                let x: u64 = t.parse().expect("Valeur non entière dans next_hop.csv");
                // Si déjà remappé (0..n-1), on garde tel quel
                if (x as usize) < n {
                    next_hop[i][j] = x;
                } else if let Some(&new_id) = orig2new.get(&x) {
                    // Sinon, remap depuis l'ID original
                    next_hop[i][j] = new_id;
                } else {
                    // ID inconnu du mapping -> pas de chemin
                    next_hop[i][j] = u64::MAX;
                }
            }
        }
    }

    // ---- 4) Contexte/clefs & messages (ton API) ----
    let mut ctx = Context::from(PARAM_MESSAGE_4_CARRY_0);
    let private_key = key(ctx.parameters);
    let public_key = &private_key.public_key;

    let dep = NLWE::from_plain(45, 2, &mut ctx, private_key);
    let arv = NLWE::from_plain(12, 2, &mut ctx, private_key);

    // ---- 5) Appel (4 paramètres) ----
    let vecteur_sp = public_key.blind_sp_big(&next_hop, dep, arv, &ctx);

    // ---- 6) Vérification/affichage ----
    for (k, nlwe) in vecteur_sp.into_iter().enumerate() {
        let clair = nlwe.to_plain(&ctx, private_key);
        println!("[{}] = {:?}", k, clair);
    }
}

